const raw = $input.first().json || {};
const src = Object.assign({}, raw.body || {}, raw.query || {}, raw);
const v = (k) => { const x = src[k]; return x == null ? '' : String(x).trim(); };
const content = v('CONTENT');
if (!content) throw new Error('CONTENT is required');
return [{ json: {
  RUN_ID: String($execution.id),
  CONTENT: content,
  ASSET_TYPES: v('ASSET_TYPES'),
  FEEDBACK: v('FEEDBACK'),
  SPEC_JSON: v('SPEC_JSON'),
} }];

const cfg = JSON.parse($('download_registry').first().json.output || '{}');
const req = $('normalize_input').first().json;
const types = Array.isArray(cfg.types) ? cfg.types : [];
const byId = new Map(types.map((t) => [t.id, t]));
const budget = cfg.budget || {};
const cap = Number(cfg.max_types_per_request || 3);
let requested = req.ASSET_TYPES
  ? req.ASSET_TYPES.split(',').map((s) => s.trim()).filter(Boolean)
  : (cfg.default_types || []);
requested = [...new Set(requested)];
const out = [];
const note = (id, status, error) => out.push({ json: Object.assign({}, req, {
  ASSET_TYPE: id, NAME: id, AUTHOR: null, TEMPLATE: null, SPEC_TEMPLATE: null,
  RENDER_MODE: '', FORMAT: '', FALLBACK_FORMAT: null, ASPECT: '', AVAILABLE: false,
  UNAVAILABLE_REASON: '', FPS: 0, FRAMES: 0, VIEWPORT: 0, STATUS, ERROR: error }) });
for (const id of requested.slice(0, cap)) {
  const t = byId.get(id);
  if (!t) { note(id, 'UNKNOWN', 'unknown asset type: ' + id); continue; }
  const b = Object.assign({}, budget, t.budget || {});
  out.push({ json: Object.assign({}, req, {
    ASSET_TYPE: t.id, NAME: t.name || t.id, AUTHOR: t.author, TEMPLATE: t.template || null,
    SPEC_TEMPLATE: t.specTemplate || null, RENDER_MODE: t.render, FORMAT: t.format,
    FALLBACK_FORMAT: t.fallbackFormat || null, ASPECT: t.aspect || '4:5',
    AVAILABLE: t.available !== false, UNAVAILABLE_REASON: t.unavailableReason || '',
    FPS: Number(b.fps || 12), FRAMES: Number(b.frames || 36), VIEWPORT: Number(b.viewport || 1200),
  }) });
}
for (const id of requested.slice(cap)) note(id, 'SKIPPED', 'over the per-request cap of ' + cap);
return out;

const req = $('normalize_input').first().json;
const wants = $('parse_registry').all().map((i) => i.json).filter((a) => a.SPEC_TEMPLATE);
const first = wants.length ? wants[0] : null;
return [{ json: Object.assign({}, req, {
  ASSET_TYPE: first ? first.ASSET_TYPE : '',
  NEEDS_SPEC: !!first,
}) }];

const raw = ($input.first().json.SPEC_JSON || '').trim();
if (!raw) return [{ json: { SPEC: null, SPEC_JSON: '' } }];
let spec;
try { spec = JSON.parse(raw); } catch (e) { throw new Error('SPEC_JSON parameter is invalid JSON: ' + e.message); }

const fail = (msg) => { throw new Error('content spec invalid: ' + msg); };
if (typeof spec.title !== 'string' || !spec.title.trim()) fail('missing field: title');
if (!Array.isArray(spec.blocks) || spec.blocks.length < 3 || spec.blocks.length > 6)
  fail('blocks must be an array of 3 to 6 entries');
spec.blocks.forEach((b, i) => {
  if (!b || typeof b.label !== 'string' || !b.label.trim()) fail('missing field: blocks[' + i + '].label');
  if (b.value == null || String(b.value).trim() === '') fail('missing field: blocks[' + i + '].value');
});
if (typeof spec.accent !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(spec.accent))
  fail('missing field: accent');
if (!spec.motion || typeof spec.motion !== 'object') fail('missing field: motion');
if (!['rise', 'fade', 'sweep', 'pulse'].includes(spec.motion.kind)) fail('missing field: motion.kind');
const d = Number(spec.motion.durationMs);
if (!Number.isFinite(d) || d < 2000 || d > 4000) fail('missing field: motion.durationMs');
if (typeof spec.alt !== 'string' || !spec.alt.trim()) fail('missing field: alt');
return [{ json: { SPEC: spec, SPEC_JSON: JSON.stringify(spec) } }];

const raw0 = $('author_spec').first().json.text || '';
let raw = raw0.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const m = raw.match(/\{[\s\S]*\}/);
if (!m) throw new Error('content spec is not JSON');
let spec;
try { spec = JSON.parse(m[0]); } catch (e) { throw new Error('content spec is invalid JSON: ' + e.message); }

const fail = (msg) => { throw new Error('content spec invalid: ' + msg); };
if (typeof spec.title !== 'string' || !spec.title.trim()) fail('missing field: title');
if (!Array.isArray(spec.blocks) || spec.blocks.length < 3 || spec.blocks.length > 6)
  fail('blocks must be an array of 3 to 6 entries');
spec.blocks.forEach((b, i) => {
  if (!b || typeof b.label !== 'string' || !b.label.trim()) fail('missing field: blocks[' + i + '].label');
  if (b.value == null || String(b.value).trim() === '') fail('missing field: blocks[' + i + '].value');
});
if (typeof spec.accent !== 'string' || !/^#[0-9a-fA-F]{6}$/.test(spec.accent))
  fail('missing field: accent');
if (!spec.motion || typeof spec.motion !== 'object') fail('missing field: motion');
if (!['rise', 'fade', 'sweep', 'pulse'].includes(spec.motion.kind)) fail('missing field: motion.kind');
const d = Number(spec.motion.durationMs);
if (!Number.isFinite(d) || d < 2000 || d > 4000) fail('missing field: motion.durationMs');
if (typeof spec.alt !== 'string' || !spec.alt.trim()) fail('missing field: alt');
return [{ json: { SPEC: spec, SPEC_JSON: JSON.stringify(spec) } }];

const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const escAttr = (s) => esc(s).replace(/"/g, "&quot;");
function buildMarkup(tmpl, spec, fps, frames, viewport, isSvg) {
  const accent = /^#[0-9a-fA-F]{6}$/.test(spec.accent || "") ? spec.accent : "#22d3ee";
  const kind = ["rise", "fade", "sweep", "pulse"].includes(spec.motion && spec.motion.kind)
    ? spec.motion.kind : "rise";
  const duration = Math.max(1000, Math.min(4000, (spec.motion && spec.motion.durationMs) || 3000));
  const blocks = (spec.blocks || []).slice(0, 6);
  const step = Math.floor(duration / (blocks.length + 1));
  let out;
  if (isSvg) {
    const top = 360, row = 150;
    const svgBlocks = blocks.map((b, i) => {
      const delay = i * step, d = Math.max(200, duration - delay), y = top + i * row;
      return `<g class="block" style="animation-delay:${delay}ms;animation-duration:${d}ms">` +
        `<text class="label" x="64" y="${y}">${esc(b.label)}</text>` +
        `<text class="value" x="1136" y="${y}" text-anchor="end">${esc(b.value)}</text>` +
        `<line class="sep" x1="64" y1="${y + 28}" x2="1136" y2="${y + 28}" /></g>`;
    }).join("\n  ");
    out = tmpl.split("%%TITLE%%").join(esc(spec.title || ""))
      .split("%%BLOCKS%%").join(svgBlocks).split("%%ACCENT%%").join(accent)
      .split("%%MOTION_ANIM%%").join(kind).split("%%DURATION_MS%%").join(String(duration))
      .split("%%FPS%%").join(String(fps)).split("%%FRAMES%%").join(String(frames))
      .split("%%VIEWPORT%%").join(String(viewport)).split("%%ALT%%").join(escAttr(spec.alt || ""));
  } else {
    const htmlBlocks = blocks.map((b, i) => {
      const delay = i * step, d = Math.max(200, duration - delay);
      return `<div class="block" style="animation-delay:${delay}ms;animation-duration:${d}ms">` +
        `<span class="label">${esc(b.label)}</span><span class="value">${esc(b.value)}</span></div>`;
    }).join("\n      ");
    out = tmpl.split("%%TITLE%%").join(esc(spec.title || ""))
      .split("%%BLOCKS%%").join(htmlBlocks).split("%%ACCENT%%").join(accent)
      .split("%%MOTION_ANIM%%").join(kind).split("%%DURATION_MS%%").join(String(duration))
      .split("%%FPS%%").join(String(fps)).split("%%FRAMES%%").join(String(frames))
      .split("%%VIEWPORT%%").join(String(viewport));
  }
  const left = out.match(/%%[A-Z_]+%%/g);
  if (left) throw new Error("unresolved template token(s): " + left.join(", "));
  return out;
}
const spec = $('spec_ready').first().json.SPEC;
const specJson = $('spec_ready').first().json.SPEC_JSON;
const htmlT = $('download_html_template').first().json.output;
const svgT = $('download_svg_template').first().json.output;
const asset = (a, status) => ({
  ASSET_TYPE: a.ASSET_TYPE, RENDER_MODE: a.RENDER_MODE || '', FORMAT: a.FORMAT || '',
  STATUS, SPEC_JSON: specJson, PROMPT: '', CONTENT_TYPE: '', ERROR: '',
  DURATION_MS: '', FRAME_COUNT: '', WIDTH: '', HEIGHT: '',
});
const out = [];
for (const item of $('parse_registry').all()) {
  const a = item.json;
  if (a.STATUS === 'UNKNOWN' || a.STATUS === 'SKIPPED') {
    out.push({ json: asset(a, a.STATUS) });
    out[out.length - 1].json.ERROR = a.ERROR || '';
    continue;
  }
  if (a.AVAILABLE === false) {
    const r = asset(a, 'UNAVAILABLE');
    r.ERROR = a.UNAVAILABLE_REASON || ('unavailable: ' + a.ASSET_TYPE);
    out.push({ json: r });
    continue;
  }
  const r = asset(a, 'AUTHORED');
  let markup = '', markupKind = '';
  if (a.AUTHOR === 'spec_markup') {
    if (a.RENDER_MODE === 'animated') { markup = buildMarkup(htmlT, spec, a.FPS, a.FRAMES, a.VIEWPORT, false); markupKind = 'text/html'; }
    else if (a.RENDER_MODE === 'text') { markup = buildMarkup(svgT, spec, a.FPS, a.FRAMES, a.VIEWPORT, true); markupKind = 'image/svg+xml'; }
  }
  r.MARKUP = markup;
  r.CONTENT_TYPE = markupKind;
  out.push({ json: Object.assign({}, a, r) });
}
return out;

const src = $('if_raster').all();
const dir = $('raster_director').all();
return $input.all().map((it, i) => {
  const a = src[i].json;
  const resp = it.json || {};
  const d0 = (resp.data && resp.data[0]) || {};
  const b64 = d0.b64_json || '';
  const media = d0.media_type || 'image/png';
  const out = Object.assign({}, a, {
    STATUS: b64 ? 'RENDERED' : 'ERROR',
    PROMPT: (dir[i] && dir[i].json.text) || '',
    IMAGE: b64 ? ('data:' + media + ';base64,' + b64) : '',
    CONTENT_TYPE: b64 ? media : '',
  });
  if (!b64) out.ERROR = 'image model returned no image';
  return { json: out };
});

const items = $input.all().map((i) => i.json);
const req = $('normalize_input').first().json;
const errors = items.filter((i) => i.ERROR).map((i) => i.ASSET_TYPE + ': ' + i.ERROR);
const payload = items.map((i) => Object.assign({}, i, {
  SPEC: undefined, MARKUP: i.CONTENT_TYPE === 'image/svg+xml' ? i.MARKUP : undefined,
}));
return [{ json: {
  RUN_ID: req.RUN_ID,
  STATUS: errors.length === 0 ? 'COMPLETE' : (items.some((i) => !i.ERROR) ? 'PARTIAL' : 'FAILED'),
  REQUEST: JSON.stringify({ ASSET_TYPES: req.ASSET_TYPES, FEEDBACK: req.FEEDBACK,
                            SPEC_GIVEN: !!req.SPEC_JSON, CONTENT_LENGTH: req.CONTENT.length }),
  RESULT: JSON.stringify(payload),
  ASSET_COUNT: String(items.length),
  ERROR: errors.join(' | ').slice(0, 2000),
} }];
